# Regression test: transparent round_corner must not leave a dark ring.
#
# Course issue #2 (upstream thumbor/thumbor#1687). With transparent=1 the
# curved edge pixels must fade through alpha and keep the source color.
# They must not stay fully opaque with their RGB scaled toward black.

import unittest

from thumbor.ext.filters import _round_corner

WIDTH = 60
HEIGHT = 60
RADIUS = 20
SOURCE = (255, 255, 255)


def _render_transparent_corner():
    # Solid opaque white RGBA source.
    data = bytes([255, 255, 255, 255]) * (WIDTH * HEIGHT)
    out = _round_corner.apply(
        1,  # anti-aliasing on
        "RGBA",
        RADIUS,
        RADIUS,
        255,
        0,
        0,
        WIDTH,
        HEIGHT,
        data,
        1,  # transparent
    )
    return bytes(out)


def _pixel(buf, x, y):
    idx = (y * WIDTH + x) * 4
    return (buf[idx], buf[idx + 1], buf[idx + 2], buf[idx + 3])


class RoundCornerTransparentFringeTestCase(unittest.TestCase):
    def setUp(self):
        self.buf = _render_transparent_corner()

    def test_edge_pixels_fade_through_alpha(self):
        # The curve must have partially transparent pixels.
        partial = 0
        for y in range(RADIUS):
            for x in range(RADIUS):
                _, _, _, a = _pixel(self.buf, x, y)
                if 0 < a < 255:
                    partial += 1
        self.assertGreater(partial, 0)

    def test_no_opaque_pixel_is_darker_than_source(self):
        # An opaque pixel on the curve whose color is darker than the
        # source is the dark ring the issue describes.
        for y in range(RADIUS):
            for x in range(RADIUS):
                r, g, b, a = _pixel(self.buf, x, y)
                if a == 255:
                    self.assertEqual(
                        (r, g, b),
                        SOURCE,
                        f"opaque dark pixel at ({x}, {y}): {(r, g, b, a)}",
                    )

    def test_edge_color_is_not_darkened(self):
        # Any pixel with partial alpha keeps the source color.
        for y in range(RADIUS):
            for x in range(RADIUS):
                r, g, b, a = _pixel(self.buf, x, y)
                if 0 < a < 255:
                    self.assertEqual(
                        (r, g, b),
                        SOURCE,
                        f"darkened edge pixel at ({x}, {y}): {(r, g, b, a)}",
                    )


if __name__ == "__main__":
    unittest.main()

# Regression test: transparent round_corner must not leave a dark ring.
#
# Course issue #2 (upstream thumbor/thumbor#1687). With transparent=1 the
# curved edge pixels must fade through alpha and keep the source color.
# They must not stay opaque with their RGB scaled toward black.

import unittest

from thumbor.ext.filters import _round_corner

WIDTH = 60
HEIGHT = 60
RADIUS = 20
SOURCE = (255, 255, 255)
FILL = (255, 0, 0)


def _render_transparent_corner():
    # Solid opaque white RGBA source; fill color red.
    data = bytes([255, 255, 255, 255]) * (WIDTH * HEIGHT)
    out = _round_corner.apply(
        1,  # anti-aliasing on
        "RGBA",
        RADIUS,
        RADIUS,
        FILL[0],
        FILL[1],
        FILL[2],
        WIDTH,
        HEIGHT,
        data,
        1,  # transparent
    )
    return bytes(out)


def _pixel(buf, x, y):
    idx = (y * WIDTH + x) * 4
    return (buf[idx], buf[idx + 1], buf[idx + 2], buf[idx + 3])


def _corner_pixels():
    for y in range(RADIUS):
        for x in range(RADIUS):
            yield x, y


class RoundCornerTransparentFringeTestCase(unittest.TestCase):
    def setUp(self):
        self.buf = _render_transparent_corner()

    def test_edge_pixels_fade_through_alpha(self):
        # The curve must contain partially transparent pixels.
        partial = [
            (x, y)
            for x, y in _corner_pixels()
            if 0 < _pixel(self.buf, x, y)[3] < 255
        ]
        self.assertGreater(len(partial), 0)

    def test_no_opaque_pixel_is_darker_than_source(self):
        # An opaque pixel on the curve whose color is darker than the
        # source is the dark ring the issue describes.
        for x, y in _corner_pixels():
            r, g, b, a = _pixel(self.buf, x, y)
            if a == 255:
                self.assertEqual(
                    (r, g, b),
                    SOURCE,
                    f"opaque dark pixel at ({x}, {y}): {(r, g, b, a)}",
                )

    def test_partial_edge_pixels_keep_source_color(self):
        # Any pixel with partial alpha keeps the source color, not black
        # and not the fill color.
        for x, y in _corner_pixels():
            r, g, b, a = _pixel(self.buf, x, y)
            if 0 < a < 255:
                self.assertEqual(
                    (r, g, b),
                    SOURCE,
                    f"darkened edge pixel at ({x}, {y}): {(r, g, b, a)}",
                )


if __name__ == "__main__":
    unittest.main()

